import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    order, tot, stack = [], {}, []
    prev = 0
    for i in range(n):
        name, t, typ = data[1 + 3 * i], int(data[2 + 3 * i]), data[3 + 3 * i]
        if typ == 'b':
            if name not in tot:
                tot[name] = 0
                order.append(name)
            if stack:
                tot[stack[-1]] += t - prev
            stack.append(name)
        else:
            tot[stack.pop()] += t - prev
        prev = t
    print('\n'.join(k + ' ' + str(tot[k]) for k in order))

